"""Generated by tools/derive_symbolic.py -- do not edit by hand.

Closed-form mass matrix and bias vector for the spatial and dual cranes,
obtained by an independent symbolic derivation (SymPy ``LagrangesMethod``).
Used as a fast path; the numeric assembler remains the reference implementation
and ``tests/test_symbolic.py`` requires the two to agree.

Convention: ``M(q) qdd = forcing(q, qd) + Q``, where ``Q`` is the vector of
non-conservative generalised forces supplied by the plant.
"""

import numpy as np
from numpy import cos, sin, sqrt


def spatial_M(x, y, l, th, ph, psi, dx, dy, dl, dth, dph, dpsi, m_bridge, m_trolley, m_payload, m_winch, izz, k_psi):
    _n = np.shape(np.asarray(x))
    M = np.zeros(_n + (6, 6))
    M[..., 0, 0] = m_payload + m_trolley
    M[..., 0, 2] = m_payload*np.sin(th)*np.cos(ph)
    M[..., 0, 3] = l*m_payload*np.cos(ph)*np.cos(th)
    M[..., 0, 4] = -l*m_payload*np.sin(ph)*np.sin(th)
    M[..., 1, 1] = m_bridge + m_payload + m_trolley
    M[..., 1, 2] = m_payload*np.sin(ph)
    M[..., 1, 4] = l*m_payload*np.cos(ph)
    M[..., 2, 0] = m_payload*np.sin(th)*np.cos(ph)
    M[..., 2, 1] = m_payload*np.sin(ph)
    M[..., 2, 2] = m_payload + m_winch
    M[..., 3, 0] = l*m_payload*np.cos(ph)*np.cos(th)
    M[..., 3, 3] = l**2*m_payload*np.cos(ph)**2
    M[..., 4, 0] = -l*m_payload*np.sin(ph)*np.sin(th)
    M[..., 4, 1] = l*m_payload*np.cos(ph)
    M[..., 4, 4] = l**2*m_payload
    M[..., 5, 5] = izz
    return M

def spatial_bias(x, y, l, th, ph, psi, dx, dy, dl, dth, dph, dpsi, m_bridge, m_trolley, m_payload, m_winch, izz, k_psi):
    _n = np.shape(np.asarray(x))
    f = np.zeros(_n + (6,))
    f[..., 0] = m_payload*(2*dl*dph*np.sin(ph)*np.sin(th) - 2*dl*dth*np.cos(ph)*np.cos(th) + dph**2*l*np.sin(th)*np.cos(ph) + 2*dph*dth*l*np.sin(ph)*np.cos(th) + dth**2*l*np.sin(th)*np.cos(ph))
    f[..., 1] = dph*m_payload*(-2*dl*np.cos(ph) + dph*l*np.sin(ph))
    f[..., 2] = (1/20000)*m_payload*(20000*dph**2*l + 20000*dth**2*l*np.cos(ph)**2 + 196133*np.cos(ph)*np.cos(th))
    f[..., 3] = (1/20000)*l*m_payload*(-40000*dl*dth*np.cos(ph) + 40000*dph*dth*l*np.sin(ph) - 196133*np.sin(th))*np.cos(ph)
    f[..., 4] = (1/20000)*l*m_payload*(-40000*dl*dph - 10000*dth**2*l*np.sin(2*ph) - 196133*np.sin(ph)*np.cos(th))
    f[..., 5] = -k_psi*psi
    return f

def dual_M(x1, x2, xc, zc, al, dx1, dx2, dxc, dzc, dal, m_trolley, m_beam, length, height, k_cable, rest):
    _n = np.shape(np.asarray(x1))
    M = np.zeros(_n + (5, 5))
    M[..., 0, 0] = m_trolley
    M[..., 1, 1] = m_trolley
    M[..., 2, 2] = m_beam
    M[..., 3, 3] = m_beam
    M[..., 4, 4] = (1/12)*length**2*m_beam
    return M

def dual_bias(x1, x2, xc, zc, al, dx1, dx2, dxc, dzc, dal, m_trolley, m_beam, length, height, k_cable, rest):
    _n = np.shape(np.asarray(x1))
    f = np.zeros(_n + (5,))
    f[..., 0] = (1/2)*k_cable*(2*rest - np.sqrt((2*height + length*np.sin(al) - 2*zc)**2 + (length*np.cos(al) + 2*x1 - 2*xc)**2))*(length*np.cos(al) + 2*x1 - 2*xc)/np.sqrt((2*height + length*np.sin(al) - 2*zc)**2 + (length*np.cos(al) + 2*x1 - 2*xc)**2)
    f[..., 1] = -1/2*k_cable*(2*rest - np.sqrt((-2*height + length*np.sin(al) + 2*zc)**2 + (length*np.cos(al) - 2*x2 + 2*xc)**2))*(length*np.cos(al) - 2*x2 + 2*xc)/np.sqrt((-2*height + length*np.sin(al) + 2*zc)**2 + (length*np.cos(al) - 2*x2 + 2*xc)**2)
    f[..., 2] = (1/2)*k_cable*((2*rest - np.sqrt((-2*height + length*np.sin(al) + 2*zc)**2 + (length*np.cos(al) - 2*x2 + 2*xc)**2))*np.sqrt((2*height + length*np.sin(al) - 2*zc)**2 + (length*np.cos(al) + 2*x1 - 2*xc)**2)*(length*np.cos(al) - 2*x2 + 2*xc) - (2*rest - np.sqrt((2*height + length*np.sin(al) - 2*zc)**2 + (length*np.cos(al) + 2*x1 - 2*xc)**2))*np.sqrt((-2*height + length*np.sin(al) + 2*zc)**2 + (length*np.cos(al) - 2*x2 + 2*xc)**2)*(length*np.cos(al) + 2*x1 - 2*xc))/(np.sqrt((-2*height + length*np.sin(al) + 2*zc)**2 + (length*np.cos(al) - 2*x2 + 2*xc)**2)*np.sqrt((2*height + length*np.sin(al) - 2*zc)**2 + (length*np.cos(al) + 2*x1 - 2*xc)**2))
    f[..., 3] = -2*height*k_cable*rest/np.sqrt((2*height + length*np.sin(al) - 2*zc)**2 + (length*np.cos(al) + 2*x1 - 2*xc)**2) - 2*height*k_cable*rest/np.sqrt((-2*height + length*np.sin(al) + 2*zc)**2 + (length*np.cos(al) - 2*x2 + 2*xc)**2) + 2*height*k_cable - k_cable*length*rest*np.sin(al)/np.sqrt((2*height + length*np.sin(al) - 2*zc)**2 + (length*np.cos(al) + 2*x1 - 2*xc)**2) + k_cable*length*rest*np.sin(al)/np.sqrt((-2*height + length*np.sin(al) + 2*zc)**2 + (length*np.cos(al) - 2*x2 + 2*xc)**2) + 2*k_cable*rest*zc/np.sqrt((2*height + length*np.sin(al) - 2*zc)**2 + (length*np.cos(al) + 2*x1 - 2*xc)**2) + 2*k_cable*rest*zc/np.sqrt((-2*height + length*np.sin(al) + 2*zc)**2 + (length*np.cos(al) - 2*x2 + 2*xc)**2) - 2*k_cable*zc - 196133/20000*m_beam
    f[..., 4] = (1/2)*k_cable*length*((2*rest - np.sqrt((-2*height + length*np.sin(al) + 2*zc)**2 + (length*np.cos(al) - 2*x2 + 2*xc)**2))*np.sqrt((2*height + length*np.sin(al) - 2*zc)**2 + (length*np.cos(al) + 2*x1 - 2*xc)**2)*(-height*np.cos(al) + x2*np.sin(al) - xc*np.sin(al) + zc*np.cos(al)) + (2*rest - np.sqrt((2*height + length*np.sin(al) - 2*zc)**2 + (length*np.cos(al) + 2*x1 - 2*xc)**2))*np.sqrt((-2*height + length*np.sin(al) + 2*zc)**2 + (length*np.cos(al) - 2*x2 + 2*xc)**2)*(height*np.cos(al) - x1*np.sin(al) + xc*np.sin(al) - zc*np.cos(al)))/(np.sqrt((-2*height + length*np.sin(al) + 2*zc)**2 + (length*np.cos(al) - 2*x2 + 2*xc)**2)*np.sqrt((2*height + length*np.sin(al) - 2*zc)**2 + (length*np.cos(al) + 2*x1 - 2*xc)**2))
    return f

